// Score = weighted performance against the vertical's own benchmark, damped by confidence.
// Comparing a plumber's CTR to a SaaS CTR on an absolute scale is meaningless; comparing
// each to its own vertical benchmark is not.
const profile = $json;
const rows = $('Envelope In').first().json.payload.metrics || [];
const bench = Object.fromEntries((profile.kpis || []).map(k => [k.metric, k.benchmark]));
const primary = (profile.kpis || []).filter(k => k.primary).map(k => k.metric);

const MIN_IMPRESSIONS = 300;
const out = rows.map(r => {
  const parts = [];
  const add = (metric, value) => { const b = bench[metric]; if (value != null && b) parts.push(Math.min(2, value / b) / 2); };
  add('engagement_rate', r.engagement_rate);
  add('click_through_rate', r.ctr);
  add('conversion_rate', r.cvr);
  add('watch_through_rate', r.watch_through_rate);
  const raw = parts.length ? parts.reduce((a, b) => a + b, 0) / parts.length : null;
  const confidence = Math.min(1, (r.impressions ?? 0) / MIN_IMPRESSIONS);
  // Shrink toward 0.5 when the sample is thin: an unproven winner is not a winner.
  const score = raw == null ? null : (raw * confidence) + (0.5 * (1 - confidence));
  return { ...r, raw_score: raw, confidence, score, decisive: confidence >= 1 && raw != null, primary_kpis: primary };
});

const ranked = out.filter(x => x.score != null).sort((a, b) => b.score - a.score);
return [{ json: {
  scored: out,
  winner: ranked.find(x => x.decisive) || null,
  top_decile_threshold: ranked.length >= 10 ? ranked[Math.floor(ranked.length * 0.1)].score : null,
  note: ranked.some(x => x.decisive) ? null : 'No result has enough impressions to be decisive yet; do not reallocate on this data.'
} }];
